#!/usr/bin/env python3
"""Build the combined report from measurements; never supplies estimated wins."""
from pathlib import Path
import base64,csv,html,json,math,re,statistics
ROOT=Path(__file__).resolve().parents[2]
BASE=Path(__file__).resolve().parent;OUT=BASE/'results'
def read(name):return json.loads((OUT/name).read_text())
def mean(values):return statistics.mean(list(values))
def geom(values):return statistics.geometric_mean(list(values))
screen=read('screen.json');quality=read('quality.json');combos=read('combinations.json');startup=read('startup.json');filters=read('filters.json')
NAMES={'bvh4':'Four-wide BVH','bvh8':'Eight-wide BVH','quantized_bvh8':'Compressed eight-wide BVH','leaf8':'BVH leaf size 8','leaf16':'BVH leaf size 16','sah32':'32-bin SAH','sah_stop':'SAH leaf-cost stopping','packed_shading':'Packed shading attributes','stochastic_color':'Stochastic color filtering','stochastic_all':'Stochastic all-map filtering','fp16_state':'FP16 path radiance/throughput','packed_directions':'Packed ray directions','skip_final_shading':'Skip final-hit shading/scatter','classify_opacity':'Material opacity classification','opacity_micromap':'Conservative software opacity cells','alpha_shrink':'Diffuse alpha-area approximation','alpha_cap4':'Cap alpha texture tests at four','blue_noise_jitter':'Spatial blue-noise / R2 jitter','bounded_vndf':'Bounded GGX VNDF','ray_cones':'Ray-cone texture mip selection','best_exact_combo':'Combined exact candidates','quality_combo':'Combined quality candidates','memory_combo':'Combined compact formats'}
rows=[]
for name,flags,kind in screen['variants']:
 s=[r for r in screen['records'] if r['variant']==name];q=[r for r in quality if r['variant']==name]
 row=dict(name=name,title=NAMES[name],flags=flags,kind=kind,speedup=geom(r['speedup'] for r in s),view_speedups={str(r['view']):r['speedup'] for r in s},raw_identical=all(r['raw_equal'] for r in s),quality_ratio=mean(r['mse_ratio'] for r in q) if q else None,radiance_ratio=mean(r['radiance_ratio'] for r in q) if q else None,max_budget_error=max((abs(r['budget_ratio']-1) for r in q),default=None),screen=s,quality=q)
 row['view_quality_ratios']={str(v):mean(t['mse_ratio'] for t in q if t['candidate']['view']==v) for v in [1,19]} if q else {}
 rows.append(row)
combined=[]
for name in dict.fromkeys(r['variant'] for r in combos):
 q=[r for r in combos if r['variant']==name]
 combined.append(dict(name=name,title=NAMES[name],flags=q[0]['candidate']['flags'],kind='combination',speedup=geom(r['baseline']['ms_per_sample']/r['candidate']['ms_per_sample'] for r in q),quality_ratio=mean(r['mse_ratio'] for r in q),radiance_ratio=mean(r['radiance_ratio'] for r in q),max_budget_error=max(abs(r['budget_ratio']-1) for r in q),raw_identical=None,quality=q))
identity_file=OUT/'combination-identities.json'
if identity_file.exists():
 identities=json.loads(identity_file.read_text())
 for row in combined:
  matches=[r for r in identities if r['variant']==row['name']]
  row['raw_identical']=len(matches)==2 and all(r['raw_identical'] for r in matches)
startup_base=statistics.median(r['process_wall_s'] for r in startup if not r['cache']);startup_cache=statistics.median(r['process_wall_s'] for r in startup if r['cache'])
filter_summary=[]
for v in [1,19]:
 b=next(r for r in filters if r['view']==v and not r['sparse']);s=next(r for r in filters if r['view']==v and r['sparse'])
 filter_summary.append(dict(view=v,baseline_p95_ms=b['filter_p95_ms'],sparse_p95_ms=s['filter_p95_ms'],speedup=b['filter_p95_ms']/s['filter_p95_ms'],mse_ratio=s['filtered_display_mse']/b['filtered_display_mse']))
summary=dict(variants=rows,combinations=combined,startup=dict(baseline_s=startup_base,cached_s=startup_cache,speedup=startup_base/startup_cache),filters=filter_summary,environment=read('environment.json'))
(OUT/'combined.json').write_text(json.dumps(summary,indent=2)+'\n')
with (OUT/'combined.csv').open('w') as f:
 w=csv.writer(f);w.writerow(['technique','kind','screen_speedup','raw_identical_32spp','equal_time_display_mse_change_pct','equal_time_radiance_mse_change_pct','max_budget_error_pct','flags','view1_speedup','view19_speedup','view1_mse_ratio','view19_mse_ratio'])
 for r in rows+combined:
  w.writerow([r['title'],r['kind'],r['speedup'],r['raw_identical'],None if r['quality_ratio'] is None else 100*(r['quality_ratio']-1),None if r['radiance_ratio'] is None else 100*(r['radiance_ratio']-1),None if r['max_budget_error'] is None else 100*r['max_budget_error'],' '.join(r['flags']),r.get('view_speedups',{}).get('1'),r.get('view_speedups',{}).get('19'),r.get('view_quality_ratios',{}).get('1'),r.get('view_quality_ratios',{}).get('19')])


def pct(r):return 'not separately tested' if r is None else f'{100*(r-1):+.1f}%'
startup_identical=all((OUT/(a['label']+'.f32')).read_bytes()==(OUT/(b['label']+'.f32')).read_bytes() for a in startup for b in startup if a['key']['seed']==b['key']['seed'])
lines=['# Combined local optimization report','',f"Measured {len(rows)} independent rendering variants, a cooked-scene cache, a sparse spatial filter, and {len(combined)} selected combinations. Application defaults remain three bounces, roulette on, every new experiment off.",'','## Results','', '| Technique | GPU speedup | Raw identical at 32 spp | Equal-time display MSE | Type |','|---|---:|---|---:|---|']
for r in sorted(rows,key=lambda r:r['speedup'],reverse=True):lines.append(f"| {r['title']} | {r['speedup']:.3f}× | {'yes' if r['raw_identical'] else 'no'} | {pct(r['quality_ratio'])} | {r['kind']} |")
exact=next((r for r in combined if r['name']=='best_exact_combo'),None)
if exact:
 lines[4:4]=['## Main finding','',f"The strongest confirmed exact-output combination was SAH leaf-cost stopping plus final-hit shading elimination: {exact['speedup']:.3f}× per-sample speedup and {100*(1-exact['quality_ratio']):.1f}% lower equal-time display error in these tests. It matched baseline raw pixels in both fixed-count checks. Adding packed attributes to that combination was less effective. Defaults were left unchanged.",'',f"The warm scene cache reduced startup wall time by {startup_base/startup_cache:.2f}×; it does not accelerate steady-state rays. Sparse spatial filtering was slower and increased image error. Small single-feature differences remain inconclusive.",'']
lines+=['','Speedup >1 is faster. Negative MSE change is better. Screen speedups are geometric means across two views, normalized against interleaved baseline controls. They are screening measurements, not formal confidence intervals. Exact same-count pixels do not imply equal-time quality was measured separately.','', '## Combinations','']
for r in combined:
 lines += [f"### {r['title']}",'',f"Measured {r['speedup']:.3f}× per-sample speedup; equal-time display MSE {pct(r['quality_ratio'])}, compressed-radiance MSE {pct(r['radiance_ratio'])}. Maximum budget mismatch {100*r['max_budget_error']:.1f}%.",'', '```sh','cargo run --release --locked -- --sponza '+' '.join(r['flags']),'```','']
lines+=['## Startup and spatial filter','',f"Warm cooked-scene cache: median process wall time {startup_base:.3f} s → {startup_cache:.3f} s ({startup_base/startup_cache:.2f}×), three alternating trials per mode, 96×64/8 spp. The cache saves loading/build work, not steady-state tracing work. Source path/metadata, relevant options and importer source fingerprint key the cache; checksum validates payload. It is limited to the supplied self-contained Sponza GLB.",'','| View | Baseline filter p95 | Sparse filter p95 | Filter speedup | Filtered display MSE change |','|---|---:|---:|---:|---:|']
for f in filter_summary:lines.append(f"| {f['view']} | {f['baseline_p95_ms']:.3f} ms | {f['sparse_p95_ms']:.3f} ms | {f['speedup']:.2f}× | {pct(f['mse_ratio'])} |")
lines += ['', 'Filter timings isolate 100 warmed dispatches. Filter-only speedup is not total-render speedup. The sparse kernel uses current-frame radiance only; it reads no history.','', '## Method','', 'Intel Iris Xe TGL GT2 / Vulkan. All rendered comparisons use native 640×400, three bounces, roulette enabled (inactive before bounce four), sky importance and prior VNDF off. No upscaling, history reprojection, lighting cache, raster primary visibility or queue/pass redesign is introduced. Original progressive accumulation is retained. Denoising is off except in the separate filter experiment.','', 'References are independent 2048-spp, three-bounce NDF renders from the VNDF experiment (seed offset 2,000,000). Screening uses 32 spp/seed 10,000 in two courtyard views (1 and 19), with baseline controls every four variants and linear interpolation of baseline GPU cost in time. Each screen point is one process run. Raw radiance identity is checked against same-seed baseline captures. The pre-sweep binary is also checked when available.','', 'Precision/sampling/appearance variants and any geometry variant with non-identical raw output receive two seeds × two views at matched warmed GPU budgets. Baseline is 64 spp; candidate count is predicted from screening and corrected up to twice to target ±3%. Actual mismatches are retained, not hidden. Candidate counts and flags are in every record. Timing excludes first frame, imports/JIT, readback and disk writes. Sorted mean GPU totals divided by warmed sample count determine budgets. Sequential runs still permit clock/temperature drift. Small differences are inconclusive.','', 'Display MSE uses float sRGB after the renderer tone curve; compressed-radiance MSE uses x/(1+x). References retain Monte Carlo noise. Changes to filtering or alpha visibility can change the target image; a lower scalar error does not establish physical equivalence. Results from two views do not establish universal wins.','', '## Implementation distinctions','', '- Four/eight-wide nodes are a local collapse of the current binary SAH tree. The compressed variant stores outward-rounded half bounds and packed metadata, 128 bytes per eight-child node. This is not the report’s specialized 80-byte CWBVH/bitmask traversal implementation. Overflow falls back to a full triangle query rather than dropping hits. Tied distances select the lowest current triangle index.', '- Packed shading vertices use 32 bytes instead of 64: positions remain float32; normals/tangents use octahedral snorm16 and UVs use half. Quantization is a quality tradeoff, including UVs used by alpha.', '- FP16 uses native f16 live radiance/throughput state, with float32 shading and final accumulation. It does not prove a particular register allocation or validate large HDR ranges outside the tested scenes. Packed directions carry an octahedral word between mesh bounces, reconstructing for traversal.', '- Stochastic color filtering samples one bilinear-weighted texel for color/emission maps; all-map mode also changes normal/roughness and alpha filtering. Nonlinear material evaluation means matching expected texel values does not guarantee matching the original BRDF.', '- Ray cones choose texture mip levels using a conservative footprint and a roughness-based spread heuristic. Color mips average in linear light; odd dimensions use area weights. Alpha tests stay at base level. This changes texture prefiltering, not output resolution. It is a heuristic prototype, not a full ray-differential implementation.', '- Material opacity classification can only remove a MASK test if every texel passes conservatively. Sponza had no such materials. Software opacity cells use a 4×4 barycentric grid with unknown/opaque/transparent states; classification scans a conservative texel rectangle, limits work, and falls back to exact alpha for unknown cells. Small classified coverage can make this slower.', '- Diffuse alpha-area approximation shrinks triangle coverage by material mean opacity for diffuse secondary rays; other rays retain alpha. The four-test cap treats further unknown alpha hits as opaque. Both can change visibility and are never considered exact winners.', '- Blue-noise primary jitter uses original toroidal void-and-cluster spatial rank masks with an R2 frame-index shift. No prior rendered pixels are read. This is not the report’s filter-trained FAST/STBN sequence.', '- Bounded VNDF uses the 2023 bounded spherical-cap sampler and its matching mixture/MIS PDF; it is separate from the prior 2018 VNDF test.', '- Final-hit skip removes unused normal/shading/BSDF work at the bounce cap while retaining emission/UVs and the three path RNG draws, preserving subsequent samples in a batch.','', '## Scope of the supplied report','', '| Report idea | Treatment |','|---|---|','| Compact hit/ray/shading state | Existing 16-byte candidates plus packed attributes, oct directions and native FP16 trials |','| Wide/compressed software BVH | Four/eight-wide and compressed prototype measured; specialized 80-byte CWBVH not claimed |','| Static BVH cooking | Leaf-size, bin-count, SAH stopping and scene-cache trials |','| Tier-C opacity alternatives | Exact classification/cells, approximate area shrink and alpha-test cap measured |','| Texture stochastic filtering / ray cones | Color-only, all-map and mip-footprint trials |','| Noise sequences / bounded GGX | Spatial blue-noise alternative and bounded VNDF measured |','| Spatial denoising | Current-frame sparse bilateral trial |','| Shared-memory stack / classic VNDF / sky sampling | Already tried earlier; historical results are not mixed into current three-bounce numbers |','| Temporal stages, reservoirs/history, radiance caches | Excluded by requested history/rearchitecture constraints |','| Screen-space trace chain, material-sorted wavefront queues, primary resolve | Require new pass/buffer architecture; excluded |','| Half-resolution rays/upscalers | Excluded by resolution/reconstruction constraint |','| Hardware RT/SER/hardware opacity micromaps/DLSS | Not applicable to this Iris Xe compute path |','| Dynamic H-PLOC, skinning, streaming, far-field HLOD, light-list infrastructure | Current static Sponza scene lacks these systems; infrastructure work rather than a local optimization |','| Watertight intersections / firefly clamps | Robustness or biased image-quality changes, not a reduction of current tracing work; not presented as speed wins |','| Native 16-bit integer counters | WGSL does not provide the report’s native u16 shader-counter representation |','', '## Reproduce','', '```sh','cargo build --release --locked','training/.venv/bin/python -m pip install -r performance/local-sweep/requirements.txt','training/.venv/bin/python -u performance/local-sweep/run.py','python3 performance/local-sweep/report.py','```','', 'Completed captures are reused only when binary fingerprint, parameters and output files match. Every render has a record, raw radiance, PNG, timing and log under results/. See combined.json, combined.csv, screen.json, quality.json, combinations.json, startup.json and filters.json. No model API is used by the runner.','', '## Validation','', 'All 27 default CPU/GPU tests passed after the sweep, including the Sponza brute-force comparison. Additional grid/parallel/inside-ray tests passed for four-wide, eight-wide and compressed eight-wide traversal; software-opacity cutout/visibility checks and bounded-VNDF energy checks also passed. Fixed-count validation confirmed raw identity for the recommended two-flag combination in both views. The pre-sweep control matched the unmodified baseline pixels. Scene-cache startup captures were also byte-identical across modes.','', '## Sources','', '- Supplied Zet architecture draft (local attachment), especially sections 5–7, 10–13.', '- [Eto and Tokuyoshi, Bounded VNDF Sampling for Smith–GGX Reflections](https://gpuopen.com/download/publications/Bounded_VNDF_Sampling_for_Smith-GGX_Reflections.pdf). The implemented sampler/PDF follows the bounded spherical-cap construction.', '- [Heitz, GGX visible normals](https://jcgt.org/published/0007/04/01/) for the previous VNDF baseline and terminology.','']
lines+=['## Per-view quality and switches','', '| Technique | View 1 GPU speedup | View 19 GPU speedup | View 1 MSE change | View 19 MSE change | Flags |','|---|---:|---:|---:|---:|---|']
for r in rows:
 lines.append(f"| {r['title']} | {r['view_speedups'].get('1',0):.3f}× | {r['view_speedups'].get('19',0):.3f}× | {pct(r['view_quality_ratios'].get('1'))} | {pct(r['view_quality_ratios'].get('19'))} | `{' '.join(r['flags'])}` |")
(BASE/'README.md').write_text('\n'.join(lines))

# Compact interactive overview plus a few representative image comparisons.
all_rows=rows+combined
examples=[]
for r in combined[:1]+sorted([r for r in rows if r['quality']],key=lambda r:r['quality_ratio'])[:1]+[r for r in rows if r['name']=='alpha_shrink']:
 if not r['quality']:continue
 pairs=[]
 for v in [1,19]:
  q=next(q for q in r['quality'] if q['candidate']['view']==v)
  pair={k:q[k] for k in ['baseline','candidate']}
  for k in ['baseline','candidate']:
   path=OUT/(pair[k]['label']+'.png');pair[k]={**pair[k],'image':'data:image/png;base64,'+base64.b64encode(path.read_bytes()).decode()}
  reference=ROOT/f'performance/vndf/results/{v:03d}_reference.png'
  pair['reference']='data:image/png;base64,'+base64.b64encode(reference.read_bytes()).decode();pair['view']=v;pairs.append(pair)
 examples.append(dict(title=r['title'],pairs=pairs))
data=[dict(title=r['title'],name=r['name'],kind=r['kind'],cost=1/r['speedup'],error=r['quality_ratio'],identical=r['raw_identical'],flags=' '.join(r['flags'])) for r in all_rows]
payload=json.dumps(dict(rows=data,examples=examples,startup=summary['startup'],filters=filter_summary))
page='''<!doctype html><html><head><meta charset="utf-8"><style>body{margin:0;font-family:var(--font-sans);color:var(--foreground)}p,label{font-size:13px}p{color:var(--muted-foreground);line-height:1.5}.controls{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:12px 0}select,button{padding:7px;background:var(--secondary);color:var(--foreground);border:1px solid var(--border);border-radius:5px}.row{margin:9px 0}.label{display:flex;justify-content:space-between;gap:12px;font-size:12px}.track{height:10px;background:var(--secondary);margin-top:4px;border-radius:3px}.fill{height:10px;background:var(--chart-1);border-radius:3px}.fill.slower{background:var(--chart-2)}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:10px}img{width:100%;display:block}img[hidden]{display:none}.note{margin-top:14px}.summary{display:flex;gap:20px;flex-wrap:wrap}</style></head><body><p>Local optimization sweep · Iris Xe · native 640×400 · three bounces<br>Baseline = 100%. Lower cost/error is better. Defaults unchanged; every candidate remains opt-in.</p><div class="controls"><label for="metric">Measure</label><select id="metric"><option value="cost">GPU cost per sample</option><option value="error">Equal-time display error</option></select><label for="scope">Group</label><select id="scope"><option value="all">All measured rendering variants</option><option value="preserving">Geometry / exact-output candidates</option><option value="changing">Sampling / precision / filtering</option><option value="combination">Confirmed combinations</option></select></div><div id="plot" role="img" aria-label="Measured optimization comparisons"></div><p id="measure-note"></p><div class="summary" id="other"></div><div class="controls"><label for="example">Image example</label><select id="example"></select><label for="view">View</label><select id="view"><option value="1">Courtyard 1</option><option value="19">Courtyard 19</option></select></div><div id="pair-label"></div><div class="grid" id="gallery"></div><p id="caption"></p><img id="large" hidden alt="Enlarged actual rendering"><p class="note">Only two views. Screening is one 32-spp run/view with interleaved controls. Precision and sampling quality tests use two seeds/view and matched GPU budgets; small differences remain inconclusive. Changes to alpha or texture filtering can change appearance. The full report records budgets, limitations and excluded architectural techniques.</p><script>
const DATA=PAYLOAD;
function plot(){let metric=document.getElementById('metric').value,scope=document.getElementById('scope').value;let rows=DATA.rows.filter(r=>scope==='all'||scope==='preserving'&&['geometry','exact'].includes(r.kind)||scope==='changing'&&['precision','sampling','approximation','filtering'].includes(r.kind)||scope==='combination'&&r.kind==='combination');if(metric==='error')rows=rows.filter(r=>r.error!==null);rows.sort((a,b)=>a[metric]-b[metric]);let maximum=Math.max(1,...rows.map(r=>r[metric]));const root=document.getElementById('plot');root.replaceChildren();rows.forEach(r=>{const row=document.createElement('div');row.className='row';const line=document.createElement('div');line.className='label';const name=document.createElement('span');name.textContent=r.title;const value=document.createElement('span');value.textContent=(100*r[metric]).toFixed(1)+'%'+(metric==='cost'&&r.identical===true?' · raw identical':'');line.append(name,value);const track=document.createElement('div');track.className='track';const fill=document.createElement('div');fill.className='fill'+(r[metric]>1?' slower':'');fill.style.width=(100*r[metric]/maximum)+'%';track.append(fill);row.append(line,track);root.append(row)});document.getElementById('measure-note').textContent=metric==='cost'?'Individual variants: fixed-work screening. Combinations: repeated matched-budget trials. Values near 100% are inconclusive.':'Only separately measured quality trials are shown. Exact same-count pixels alone do not measure equal-time error.';}
const example=document.getElementById('example');DATA.examples.forEach((e,i)=>{const option=document.createElement('option');option.value=i;option.textContent=e.title;example.append(option)});
function gallery(){let e=DATA.examples[Number(example.value)];if(!e)return;let pair=e.pairs.find(p=>p.view===Number(document.getElementById('view').value));document.getElementById('pair-label').textContent='GPU time: baseline '+(pair.baseline.gpu_total_ms/1000).toFixed(2)+' s · candidate '+(pair.candidate.gpu_total_ms/1000).toFixed(2)+' s';let root=document.getElementById('gallery');root.replaceChildren();[['Baseline · '+pair.baseline.spp+' spp',pair.baseline.image],['Candidate · '+pair.candidate.spp+' spp',pair.candidate.image],['Reference · 2048 spp',pair.reference]].forEach(([label,src])=>{let item=document.createElement('div'),button=document.createElement('button'),image=document.createElement('img');button.textContent=label;image.src=src;image.alt=label;button.onclick=()=>{let large=document.getElementById('large');large.src=src;large.hidden=false;document.getElementById('caption').textContent=label};item.append(button,image);root.append(item)});}
document.getElementById('metric').onchange=plot;document.getElementById('scope').onchange=plot;example.onchange=gallery;document.getElementById('view').onchange=gallery;const other=document.getElementById('other');other.textContent='Warm scene-cache startup: '+DATA.startup.baseline_s.toFixed(2)+' → '+DATA.startup.cached_s.toFixed(2)+' s. Sparse-filter p95: '+DATA.filters.map(r=>r.baseline_p95_ms.toFixed(2)+' → '+r.sparse_p95_ms.toFixed(2)+' ms').join(' / ')+'. Filter speed is not total-render speed.';plot();gallery();
</script></body></html>'''.replace('PAYLOAD',payload)
(OUT/'combined-report.html').write_text(page)
print('Combined report:',BASE/'README.md')
